/* @lc app=leetcode id=3445 lang=kotlin */ class Solution { fun maxDifference(s: String, k: Int): Int = (0..4).flatMap { a -> (0..4).filter { it != a }.map { b -> a to b } }.maxOf { (a, b) -> s.runningFold(0) { c, ch -> c + if (ch - '0' == a) 1 else 0 }.let { pa -> s.runningFold(0) { c, ch -> c + if (ch - '0' == b) 1 else 0 }.let { pb -> Array(2) { IntArray(2) { 1_000_000 } }.let { best -> (0..s.length).fold(0 to -1_000_000) { (l, ans), r -> generateSequence(l) { ll -> if (r - ll >= k && pb[r] - pb[ll] >= 2) best[pa[ll] % 2].set(pb[ll] % 2, minOf(best[pa[ll] % 2][pb[ll] % 2], pa[ll] - pb[ll])).let { ll + 1 } else null }.last().let { l2 -> l2 to maxOf(ans, if (best[1 - pa[r] % 2][pb[r] % 2] < 1_000_000) pa[r] - pb[r] - best[1 - pa[r] % 2][pb[r] % 2] else -1_000_000) } }.second } } } } }